inline int AvatarRecommendationJob(uint32_t id){size_t lo=0,hi=sizeof(kAvatarRecommendationJobs)/sizeof(kAvatarRecommendationJobs[0]);while(lo<hi){size_t mid=lo+(hi-lo)/2;if(kAvatarRecommendationJobs[mid].item<id)lo=mid+1;else hi=mid;}return lo<sizeof(kAvatarRecommendationJobs)/sizeof(kAvatarRecommendationJobs[0])&&kAvatarRecommendationJobs[lo].item==id?kAvatarRecommendationJobs[lo].job:-1;}
inline int ResolveAvatarRecommendationJob(uint32_t id,int nativeJob){int job=AvatarRecommendationJob(id);return job>=0?job:nativeJob;}
